{
  "API_calls": [],
  "collected_information": {
    "python_version": "3.12+",
    "package_managers": {
      "backend": "uv (https://docs.astral.sh/uv/)",
      "frontend": "bun (https://github.com/oven-sh/bun#install)"
    },
    "env_configuration": {
      "copy_dot_env": "cp .env.example .env",
      "edit_env_file": "Edit .env with API keys and preferences",
      "config_guide": "docs/CONFIGURATION_GUIDE.md"
    },
    "installation_steps": [
      "Clone repo: git clone https://github.com/ValueCell-ai/valuecell.git",
      "cd valuecell"
    ],
    "backend_dependencies_install": [
      "cd python",
      "uv sync --extra dev (preferred)",
      "uv pip install --editable '.[dev]' (alternative)"
    ],
    "frontend_dependencies_install": [
      "cd frontend",
      "bun install"
    ],
    "running_backend": "python -m valuecell.server.main",
    "test_run_commands": {
      "run_all_tests": "make test",
      "run_specific_test_file": "uv run pytest ./python/valuecell/path/to/test.py"
    },
    "CI_details": {
      "python_version_file": "./python/pyproject.toml",
      "dependencies_install": "uv sync --locked --all-extras --dev",
      "test_commands": [
        "uv run pytest valuecell/core/ --cov=valuecell.core --cov-report=xml --cov-report=term",
        "uv run diff-cover coverage.xml --fail-under=90"
      ]
    },
    "notes": [
      "No direct requirements.txt or explicit Python versions besides 3.12+",
      "Environment variables are managed mainly via an editable .env file",
      "Frontend test guidelines are still being established"
    ]
  },
  "terminate": true
}
